{
  "ready": true,
  "brief": "A high-contrast, urgent visual showing a modern industrial rooftop in North India with a sleek solar array installation in progress, overlaid with a bold red 'DEADLINE' stamp and the date '31 DEC'. The copy leads with the critical regulatory change: 'Non-DCR solar banned from Dec 31. Costs rise by ₹10,000+ per kW.' The hook is the immediate financial risk: 'Don't let a policy change eat your profits.' The offer is the 'Free Site Survey' to lock in current rates before the ban. The mood is professional yet alarming, leveraging the brand's engineering credibility (IIT/PEC backed) to assure factory owners that this is a serious, solvable business issue, not just a sales pitch. The visual should feel like a business alert, not a generic eco-friendly poster.",
  "language": "en",
  "angleId": "urgency",
  "recommendations": [
    {
      "label": "Financial Loss Calculator",
      "prompt": "Create a version that shows a simple graphic comparing 'Cost Now' vs 'Cost After Dec 31' for a 100kW system, highlighting the specific rupee difference to make the urgency tangible."
    },
    {
      "label": "Trust & Compliance Angle",
      "prompt": "Shift the focus to the engineering team, showing IIT/PEC graduates in site surveys, emphasizing that SOLARIDE ensures full DCR compliance so factory owners avoid legal and financial pitfalls."
    },
    {
      "label": "Local Urgency",
      "prompt": "Focus specifically on factories in Mohali and Hisar, using a map visual to show local teams ready to install before the deadline, reinforcing the 'local and fast' advantage."
    }
  ]
}

