"ready": true,
"brief": "A high-stakes, urgent visual of a modern industrial factory roof in North India, bathed in harsh sunlight, with a bold, red 'STOP' style graphic overlaying a calendar page showing December 31st. The copy headline reads: 'The 31st is coming. Your costs are going up.' Subtext: 'Non-DCR solar banned. Installation costs jump by ₹10,000+ per kW. Install before the deadline to lock in your savings.' The mood is professional but pressing, emphasizing that waiting is expensive. The CTA is 'Book Your Free Site Survey Today.'",
"language": "en",
"angleId": "urgency",
"recommendations": [
{
"label": "Visual Contrast: Before vs. After",
"prompt": "Create a split-screen image: on the left, a stressed factory owner looking at a high electricity bill; on the right, the same person smiling while looking at a solar dashboard showing savings. Headline: 'Don't let the 31st deadline surprise you. Secure your savings now.'"
},
{
"label": "Authority & Engineering Focus",
"prompt": "Show a professional engineer in a hard hat inspecting a commercial rooftop solar array. Headline: 'Engineered for Compliance. IIT & PEC Backed. Install before the non-DCR ban hits your budget.'"
}
]
}

{
  "ready": true,
  "brief": "A high-stakes, urgent visual focusing on a modern industrial factory roof in North India under a clear, bright sky. The image features a close-up of a sleek, dark solar panel with a bold, red 'BANNED' or 'COST UP' graphic overlaying a specific section, contrasting with the 'SAFE' installed area, symbolizing the immediate financial threat of the new regulations. The mood is serious and professional, leveraging the 'Urgency' angle to drive immediate action. The headline copy reads: 'The 31st December Deadline: Don't Let Your Factory Pay the Penalty.' The sub-headline states: 'Non-DCR solar panels are banned, adding ₹10,000+ per kW to your costs. Secure your compliant installation now.' The call-to-action is a prominent button: 'Book Free Compliance Survey'. The visual style is clean and corporate, using the brand's professional voice to reassure factory owners that Solaride’s local engineering team can handle the transition before the deadline, highlighting the 'Free Site Survey' as the low-risk next step.",
  "language": "en",
  "angleId": "urgency",
  "recommendations": [
    {
      "label": "Financial Loss Visualization",
      "prompt": "Create a split-screen image: on the left, a factory owner looking stressed at a calculator with a red arrow pointing up labeled '₹10,000+ per kW'; on the right, the same owner smiling while shaking hands with a Solaride engineer, with a green checkmark labeled 'Compliant & Saved'. Headline: 'The Cost of Waiting is Real. Install Before Dec 31.'"
    },
    {
      "label": "Local Engineering Trust",
      "prompt": "Show a Solaride engineer in a branded uniform inspecting a factory rooftop in Punjab or Haryana, with a background of solar panels. Overlay text: 'IIT Bombay & PEC Graduates. Local Teams. Zero Regulatory Surprises.' Headline: 'Navigate the New Solar Rules with Experts Who Know Your Region.'"
    },
    {
      "label": "Bill Reduction Focus",
      "prompt": "A close-up of a factory electricity bill with the 'Solaride' logo stamped on it, showing a dramatic drop in the total amount (visual representation of 98% reduction). Text overlay: 'Cut Industrial Power Bills by Up to 98% Before the Ban Hits.' Headline: 'Turn Your Roof Into a Power Plant, Not a Cost Center.'"
    }
  ]
}

{
  "ready": true,
  "brief": "A high-stakes, urgent visual narrative targeting factory owners in North India. The image features a close-up of a heavy, industrial solar panel being lifted by a crane onto a factory roof, with a stark red 'STOP' or 'DEADLINE' graphic overlaying the horizon to symbolize the regulatory shift. The mood is professional yet alarming, emphasizing the financial risk of inaction. The copy hook is direct and factual: 'The 31st December DCR Ban is Coming.' The body copy explains that non-DCR solar panels will be banned, increasing installation costs by over ₹10,000 per kW. The offer is the immediate call to action: 'Secure your pre-deadline installation now.' The tone is transparent and mission-driven, leveraging the brand's engineering credibility (IIT Bombay/PEC Chandigarh) to reassure factory owners that SOLARIDE handles the complex compliance and installation seamlessly. The visual style is clean, industrial, and high-contrast to convey authority and urgency.",
  "language": "en",
  "angleId": "urgency",
  "recommendations": [
    {
      "label": "Cost Comparison Infographic",
      "prompt": "Create a split-screen visual: left side shows a factory owner looking stressed with a high electricity bill and a calendar marked '31 Dec'; right side shows the same owner relaxed with a low bill and a 'DCR Compliant' badge. Overlay text highlighting the '₹10,000+ per kW cost increase' to visualize the financial pain point."
    },
    {
      "label": "Engineering Trust Focus",
      "prompt": "Feature the SOLARIDE engineering team in professional attire standing in front of a large commercial solar array. The copy focuses on the 'IIT Bombay & PEC Chandigarh' backing, positioning the brand as the technical expert who can navigate the new DCR regulations safely, shifting the angle from urgency to trust and competence."
    },
    {
      "label": "Local Factory Scene",
      "prompt": "Show a specific industrial landscape in Mohali or Hisar with a modern factory roof fully covered in solar panels. The copy emphasizes 'Local Teams, Local Compliance' to reassure factory owners that the installation is handled by neighbors who understand the specific regional regulatory landscape, enhancing the 'Trusted & Local' angle."
    }
  ]
}

{
  "ready": true,
  "brief": "A high-stakes, urgent visual of a modern factory rooftop in North India, bathed in the harsh midday sun, with a bold red countdown timer overlaying the sky. The copy hooks with 'The 31st is coming. The price is going up.' It explicitly states that non-DCR solar panels are being banned, adding over ₹10,000 per kW to installation costs. The call to action is direct: 'Install before the deadline to lock in current rates.' The mood is professional and alert, leveraging the 'urgency' angle to drive immediate action from factory owners in Chandigarh, Panchkula, and Mohali who need to avoid the impending cost hike.",
  "language": "en",
  "angleId": "urgency",
  "recommendations": [
    {
      "label": "Cost Comparison Visual",
      "prompt": "Create a split-screen ad showing a 'Before 31st' side with a lower cost tag and an 'After 31st' side with a red, higher cost tag, highlighting the specific ₹10,000+ per kW increase to make the financial impact tangible."
    },
    {
      "label": "Local Compliance Expert",
      "prompt": "Feature a professional engineer from the Solaride team standing in front of a factory, holding a DCR compliance document, with a headline 'We handle the DCR paperwork. You save the money.' to build trust in the technical complexity of the ban."
    },
    {
      "label": "Bill Reduction Focus",
      "prompt": "Shift the focus from the ban to the savings, showing a factory owner looking at a significantly reduced electricity bill, with the headline 'Beat the ban, slash your bills by up to 98%.' to reframe the urgency as an opportunity."
    }
  ]
}
